import{_ as o,l as s,o as e,c as n,v as t,p as l,x as r,d,i as p,S as h}from"./chunks/framework.InCnrqk-.js";const z=JSON.parse('{"title":"编译器模糊测试 Csmith","description":"","frontmatter":{"title":"编译器模糊测试 Csmith","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/compiler-fuzzing.md","filePath":"cs/compiler-fuzzing.md","lastUpdated":1789023840000}'),c={name:"cs/compiler-fuzzing.md"};function m(C,a,u,_,f,g){const i=s("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="编译器模糊测试-csmith" tabindex="-1">编译器模糊测试 Csmith <a class="header-anchor" href="#编译器模糊测试-csmith" aria-label="Permalink to &quot;编译器模糊测试 Csmith&quot;">​</a></h1><div class="epigraph"><p>随机生成仍属于定义行为的 C 程序，在多个编译器或优化级别间比较输出。差异则是 bug。这是测试，不是 CompCert 的证明。</p><footer>—— 据 Yang, Chen, Eide and Regehr, Finding and Understanding Bugs in C Compilers, 2011；对照 CompCert 整理</footer></div><p>上一课<a href="/cs/compcert-correctness">CompCert</a> 给出证明路线。缺口是对 <strong>GCC/LLVM</strong> 的找虫：Csmith 生成避免 UB 的程序，差分测试。自举下一课收束课程。不发明 arXiv；Yang et al. PLDI 2011 是锚。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>手写用例覆盖不到优化组合。随机程序太大，若含 UB，差分无意义（优化可合法不同）。Csmith：静态避免许多 UB（不越界、不未初始化用、谨慎有符号溢出）。缺口是<strong>生成器纪律 + 差分</strong>，不是 Coq 战术。</p><p>发现：未定义假设过强、错误的别名、错误的卷绕。</p><h3 id="fuzz-不是证明" tabindex="-1">fuzz 不是证明 <a class="header-anchor" href="#fuzz-不是证明" aria-label="Permalink to &quot;fuzz 不是证明&quot;">​</a></h3><p>未找到 bug ≠ 正确。与 CompCert 互补：一个保子集，一个打工业编译器。</p><p><span class="marginnote">Yang et al. 2011 PLDI。Regehr 组后续 C-Reduce。本课不把 AFL 当 C 语义生成器；AFL 不保证无 UB。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>生成 → 多编译器运行 → 比 stdout/返回值。失败：缩减（C-Reduce）得小用例。也可对解释器/CompCert 当参考。</p>',11)),(e(),l(h,null,{default:r(()=>[p(i,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20GEN%5B%22Csmith%20%E7%94%9F%E6%88%90%22%5D%20--%3E%20C1%5B%22%E7%BC%96%E8%AF%91%E5%99%A8%20A%22%5D%0A%20%20GEN%20--%3E%20C2%5B%22%E7%BC%96%E8%AF%91%E5%99%A8%20B%22%5D%0A%20%20C1%20--%3E%20DIFF%5B%22%E5%B7%AE%E5%88%86%22%5D%0A%20%20C2%20--%3E%20DIFF%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>与<a href="/cs/language-memory-model">内存模型</a>：并发生成更难，Csmith 以单线程为主。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>超时、栈溢出要当测试工具问题。优化级别 <code>-O0</code> vs <code>-O2</code> 也是差分对。不要用含 UB 的还原用例去「证明编译器坏」。</p><p>覆盖：随机仍有盲区（某条稀有 IR 形状）。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写自举。后课默认：工业编译器用生成+差分找虫。下一课自举：编译器用自己编译自己。</p><p>也不把 fuzz 当网络协议 fuzz 教程。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Csmith：无 UB 随机 C + 差分测试找编译器 bug。</li><li>与形式化验证互补，不是替代。</li><li>缩减得到可报告用例。</li><li>出处：Yang, Chen, Eide and Regehr, 2011。</li></ul>',9))])}const A=o(c,[["render",m]]);export{z as __pageData,A as default};
